settings.custom_css:
// ── Hero Section ──
.hero-section {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  overflow: hidden;
}

// ── Background Image ──
.hero-bg {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

// Dark gradient overlay for text contrast
.hero-bg::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(
    135deg,
    rgba(26, 26, 20, 0.85) 0%,
    rgba(26, 26, 20, 0.6) 50%,
    rgba(26, 26, 20, 0.75) 100%
  );
}

// ── Content Container ──
.hero-container {
  position: relative;
  z-index: 10;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 80px;
  width: 100%;
}

// ── Main Content Grid ──
.hero-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
  min-height: calc(100vh - 160px);
  padding: 80px 0;
}

// ── Left: Text Content ──
.hero-text {
  max-width: 600px;
}

// ── Eyebrow ──
.hero-eyebrow {
  font-family: 'Cinzel', serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 5px;
  text-transform: uppercase;
  color: #C4942A;
  margin-bottom: 24px;
  opacity: 0;
  animation: fadeInUp 0.8s ease forwards 0.2s;
}

// ── Main Title ──
.hero-title {
  font-family: 'Cinzel', serif;
  font-size: clamp(48px, 6vw, 80px);
  font-weight: 600;
  line-height: 1.05;
  letter-spacing: -0.02em;
  color: #FAF8F3;
  margin: 0 0 32px 0;
  opacity: 0;
  animation: fadeInUp 0.8s ease forwards 0.4s;
}

.hero-title-line {
  display: block;
}

.hero-title-line:last-child {
  background: linear-gradient(135deg, #C4942A, #E8BC5A);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

// ── Subtitle ──
.hero-subtitle {
  font-family: 'Lato', sans-serif;
  font-size: clamp(16px, 1.2vw, 20px);
  line-height: 1.8;
  color: rgba(250, 248, 243, 0.8);
  margin: 0 0 48px 0;
  max-width: 480px;
  opacity: 0;
  animation: fadeInUp 0.8s ease forwards 0.6s;
}

// ── CTA Group ──
.hero-cta {
  display: flex;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
  opacity: 0;
  animation: fadeInUp 0.8s ease forwards 0.8s;
}

.hero-cta-primary {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 20px 40px;
  background: linear-gradient(135deg, #C4942A, #E8BC5A);
  color: #2C2416;
  font-family: 'Cinzel', serif;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-decoration: none;
  border-radius: 4px;
  transition: all 0.4s ease;
}

.hero-cta-primary:hover {
  transform: translateY(-3px);
  box-shadow: 0 20px 40px rgba(196, 148, 42, 0.3);
}

.hero-cta-primary svg {
  width: 16px;
  height: 16px;
  fill: currentColor;
  transition: transform 0.3s ease;
}

.hero-cta-primary:hover svg {
  transform: translateX(4px);
}

.hero-cta-secondary {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: rgba(250, 248, 243, 0.7);
  font-family: 'Lato', sans-serif;
  font-size: 14px;
  font-weight: 400;
  text-decoration: none;
  transition: color 0.3s ease;
}

.hero-cta-secondary:hover {
  color: #C4942A;
}

.hero-cta-secondary svg {
  width: 20px;
  height: 20px;
  fill: currentColor;
}

// ── Stats Bar ──
.hero-stats {
  display: flex;
  gap: 48px;
  margin-top: 64px;
  padding-top: 48px;
  border-top: 1px solid rgba(250, 248, 243, 0.15);
  opacity: 0;
  animation: fadeInUp 0.8s ease forwards 1s;
}

.hero-stat {
  text-align: left;
}

.hero-stat-number {
  font-family: 'Cinzel', serif;
  font-size: clamp(32px, 3vw, 48px);
  font-weight: 600;
  color: #C4942A;
  line-height: 1;
  margin-bottom: 8px;
}

.hero-stat-label {
  font-family: 'Lato', sans-serif;
  font-size: 12px;
  font-weight: 400;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: rgba(250, 248, 243, 0.5);
}

// ── Right: Image ──
.hero-image-wrap {
  position: relative;
  height: calc(100vh - 160px);
  max-height: 700px;
  opacity: 0;
  animation: fadeIn 1.2s ease forwards 0.6s;
}

.hero-image-frame {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 8px;
  overflow: hidden;
}

.hero-image-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

// Decorative frame lines
.hero-image-frame::before {
  content: '';
  position: absolute;
  top: -20px;
  right: -20px;
  width: 100%;
  height: 100%;
  border: 1px solid #C4942A;
  border-radius: 8px;
  opacity: 0.3;
  z-index: -1;
}

.hero-image-frame::after {
  content: '';
  position: absolute;
  bottom: -12px;
  left: -12px;
  width: 200px;
  height: 200px;
  background: radial-gradient(circle, #C4942A 0%, transparent 70%);
  opacity: 0.15;
  z-index: -1;
}

// ── Social Proof Bar ──
.hero-social-proof {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 20;
  padding: 24px 0;
  background: rgba(26, 26, 20, 0.9);
  backdrop-filter: blur(10px);
  border-top: 1px solid rgba(250, 248, 243, 0.08);
}

.hero-social-proof-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 80px;
  display: flex;
  align-items: center;
  gap: 48px;
}

.hero-social-proof-label {
  font-family: 'Lato', sans-serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: rgba(250, 248, 243, 0.4);
  white-space: nowrap;
}

.hero-social-proof-logos {
  display: flex;
  align-items: center;
  gap: 40px;
  flex-wrap: wrap;
}

.hero-social-proof-logo {
  font-family: 'Cinzel', serif;
  font-size: 14px;
  font-weight: 600;
  color: rgba(250, 248, 243, 0.35);
  letter-spacing: 1px;
  transition: color 0.3s ease;
}

.hero-social-proof-logo:hover {
  color: rgba(250, 248, 243, 0.7);
}

// ── Scroll Indicator ──
.hero-scroll {
  position: absolute;
  bottom: 100px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 15;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  opacity: 0;
  animation: fadeIn 1s ease forwards 1.2s;
}

.hero-scroll-text {
  font-family: 'Lato', sans-serif;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: rgba(250, 248, 243, 0.4);
}

.hero-scroll-line {
  width: 1px;
  height: 48px;
  background: linear-gradient(to bottom, #C4942A, transparent);
  animation: scrollPulse 2s ease-in-out infinite;
}

@keyframes scrollPulse {
  0%, 100% { opacity: 0.3; transform: scaleY(0.8); }
  50% { opacity: 0.8; transform: scaleY(1); }
}

// ── Animations ──
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}

// ── Responsive ──
@media (max-width: 1200px) {
  .hero-container,
  .hero-social-proof-inner {
    padding: 0 40px;
  }

  .hero-content {
    grid-template-columns: 1fr;
    gap: 48px;
    text-align: center;
  }

  .hero-text {
    max-width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
  }

  .hero-subtitle {
    max-width: 600px;
  }

  .hero-cta {
    justify-content: center;
  }

  .hero-stats {
    justify-content: center;
  }

  .hero-image-wrap {
    display: none;
  }
}

@media (max-width: 767px) {
  .hero-container,
  .hero-social-proof-inner {
    padding: 0 24px;
  }

  .hero-content {
    padding: 60px 0 120px;
    min-height: auto;
  }

  .hero-stats {
    gap: 32px;
  }

  .hero-social-proof-label {
    display: none;
  }

  .hero-social-proof-logos {
    justify-content: center;
  }

  .hero-scroll {
    display: none;
  }
}

// ── Header Base ──
selector.ao-header-wrap {
  position: sticky !important;
  top: 0;
  z-index: 1000;
  width: 100%;
}

selector.ao-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  min-height: 88px;
  padding: 0 48px;
  background: rgba(255, 253, 248, 0.92);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid rgba(196, 148, 42, 0.08);
  transition: all 0.4s ease;
}

/* Scroll state - slightly more opaque */
.ao-header-scrolled .ao-header {
  background: rgba(255, 253, 248, 0.98);
  box-shadow: 0 4px 30px rgba(44, 36, 22, 0.06);
}

// ── Logo ──
.ao-logo {
  display: flex;
  align-items: center;
  gap: 14px;
  text-decoration: none;
  flex-shrink: 0;
}

.ao-logo-icon {
  width: 42px;
  height: 42px;
  background-image: url(https://abhayoyun.org/wp-content/uploads/icon1.png);
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  filter: brightness(0) saturate(100%) sepia(50%) saturate(450%) hue-rotate(5deg) brightness(0.85);
  transition: transform 0.3s ease;
}

.ao-logo:hover .ao-logo-icon {
  transform: scale(1.05);
}

.ao-logo-text {
  font-family: 'Cinzel', serif;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: 0.1em;
  color: #2C2416;
  line-height: 1;
}

.ao-logo-text span {
  color: #C4942A;
}

.ao-logo-sub {
  font-family: 'Lato', sans-serif;
  font-size: 7px;
  font-weight: 400;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: #8B7B65;
  margin-top: 4px;
  opacity: 0.8;
}

// ── Navigation ──
.ao-nav {
  display: flex;
  align-items: center;
  gap: 44px;
}

.ao-nav-link {
  font-family: 'Lato', sans-serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #5C4A32;
  text-decoration: none;
  position: relative;
  padding: 4px 0;
  transition: color 0.3s ease;
}

.ao-nav-link::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: linear-gradient(90deg, #C4942A, #E8BC5A);
  transition: width 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.ao-nav-link:hover {
  color: #C4942A;
}

.ao-nav-link:hover::after {
  width: 100%;
}

// ── Right Section ──
.ao-header-right {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.ao-social {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-right: 8px;
}

.ao-social-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: #F8F3E8;
  color: #8B7B65;
  font-family: 'Lato', sans-serif;
  font-size: 10px;
  font-weight: 700;
  text-decoration: none;
  transition: all 0.3s ease;
}

.ao-social-link:hover {
  background: #C4942A;
  color: #fff;
  transform: translateY(-2px);
}

.ao-cta {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 12px 28px;
  background: linear-gradient(135deg, #C4942A, #E8BC5A);
  color: #fff;
  font-family: 'Cinzel', serif;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-decoration: none;
  border-radius: 100px;
  box-shadow: 0 4px 20px rgba(196, 148, 42, 0.3);
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.ao-cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 32px rgba(196, 148, 42, 0.45);
}

.ao-cta-icon {
  font-size: 12px;
  transition: transform 0.3s ease;
}

.ao-cta:hover .ao-cta-icon {
  transform: translateX(3px);
}

// ── Mobile Menu Button ──
.ao-mobile-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 36px;
  height: 36px;
  background: #F8F3E8;
  border-radius: 8px;
  cursor: pointer;
  padding: 8px;
}

.ao-mobile-toggle span {
  display: block;
  width: 100%;
  height: 2px;
  background: #5C4A32;
  border-radius: 2px;
  transition: all 0.3s ease;
}

// ── Mobile Navigation ──
.ao-mobile-nav {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: #FFFDF8;
  border-bottom: 1px solid rgba(196, 148, 42, 0.1);
  padding: 24px;
  box-shadow: 0 8px 40px rgba(44, 36, 22, 0.08);
}

.ao-mobile-nav.active {
  display: block;
  animation: slideDown 0.3s ease;
}

.ao-mobile-nav .ao-nav-link {
  display: block;
  padding: 14px 0;
  font-size: 13px;
  border-bottom: 1px solid #EDE4D3;
}

.ao-mobile-nav .ao-nav-link:last-child {
  border-bottom: none;
}

// ── Animations ──
@keyframes slideDown {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

// ── Responsive ──
@media (max-width: 1024px) {
  .ao-nav { gap: 28px; }
  .ao-nav-link { font-size: 10px; letter-spacing: 1.5px; }
  .ao-social { display: none; }
}

@media (max-width: 767px) {
  .ao-header {
    min-height: 68px;
    padding: 0 20px;
  }

  .ao-nav { display: none; }
  .ao-social { display: none; }
  .ao-cta { display: none; }

  .ao-mobile-toggle { display: flex; }

  .ao-logo-text { font-size: 18px; }
  .ao-logo-sub { display: none; }
}

// ── Section Container ──
.about-section {
  position: relative;
  overflow: hidden;
}

// ── Decorative Elements ──
@keyframes float-slow {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-15px) rotate(2deg); }
}

@keyframes glow-pulse {
  0%, 100% { opacity: 0.15; transform: scale(1); }
  50% { opacity: 0.25; transform: scale(1.1); }
}

.about-deco-1 {
  position: absolute;
  top: -100px;
  left: -100px;
  width: 300px;
  height: 300px;
  border-radius: 50%;
  background: radial-gradient(circle, #F5DFA0 0%, transparent 70%);
  opacity: 0.3;
  animation: glow-pulse 8s ease-in-out infinite;
  pointer-events: none;
}

.about-deco-2 {
  position: absolute;
  bottom: -80px;
  right: -80px;
  width: 250px;
  height: 250px;
  border-radius: 50%;
  background: radial-gradient(circle, #6B8F5C 0%, transparent 70%);
  opacity: 0.15;
  animation: glow-pulse 10s ease-in-out infinite reverse;
  pointer-events: none;
}

// ── Image Styling ──
.about-image-wrap {
  position: relative;
  display: inline-block;
}

.about-image-frame {
  position: absolute;
  top: -16px;
  left: -16px;
  right: 16px;
  bottom: 16px;
  border: 2px solid #F5DFA0;
  border-radius: 24px;
  opacity: 0.4;
  pointer-events: none;
}

.about-image-frame-2 {
  position: absolute;
  top: -8px;
  left: -8px;
  right: 8px;
  bottom: 8px;
  border: 1px solid #C4942A;
  border-radius: 20px;
  opacity: 0.25;
  pointer-events: none;
}

.about-image-main {
  position: relative;
  border-radius: 20px;
  overflow: hidden;
  box-shadow: 0 24px 60px rgba(44, 36, 22, 0.12);
  transition: all 0.6s ease;
}

.about-image-main:hover {
  transform: scale(1.02);
  box-shadow: 0 32px 80px rgba(44, 36, 22, 0.16);
}

.about-image-main img {
  width: 100%;
  height: auto;
  display: block;
  border-radius: 20px;
}

.about-image-caption {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 20px;
  background: linear-gradient(to top, rgba(44, 36, 22, 0.7), transparent);
  color: #fff;
  font-family: 'Cinzel', serif;
  font-size: 11px;
  letter-spacing: 3px;
  text-transform: uppercase;
  text-align: center;
}

// ── Content Styling ──
.about-eyebrow {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 20px;
}

.about-eyebrow-line {
  width: 40px;
  height: 1px;
  background: linear-gradient(to right, transparent, #C4942A);
}

.about-eyebrow-text {
  font-family: 'Cinzel', serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 5px;
  text-transform: uppercase;
  color: #C4942A;
}

.about-title {
  font-family: 'Cinzel', serif;
  font-size: clamp(36px, 4vw, 52px);
  line-height: 1.1;
  letter-spacing: -0.5px;
  color: #2C2416;
  margin-bottom: 24px;
}

.about-title-accent {
  display: block;
  background: linear-gradient(135deg, #C4942A, #E8BC5A);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.about-text {
  font-family: 'Lato', sans-serif;
  font-size: 16px;
  line-height: 2;
  color: #5C4A32;
  margin-bottom: 16px;
  opacity: 0;
  animation: fadeInUp 0.8s ease forwards;
}

.about-text:nth-child(2) { animation-delay: 0.2s; }
.about-text:nth-child(3) { animation-delay: 0.4s; }

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

// ── Stats Grid ──
.about-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
  padding-top: 36px;
  border-top: 2px solid rgba(196, 148, 42, 0.15);
}

.about-stat {
  text-align: center;
  padding: 0 12px;
  opacity: 0;
  animation: fadeInUp 0.6s ease forwards;
}

.about-stat:nth-child(1) { animation-delay: 0.3s; }
.about-stat:nth-child(2) { animation-delay: 0.45s; }
.about-stat:nth-child(3) { animation-delay: 0.6s; }

.about-stat-number {
  font-family: 'Cinzel', serif;
  font-size: clamp(40px, 4vw, 52px);
  font-weight: 600;
  line-height: 1;
  margin-bottom: 8px;
  background: linear-gradient(135deg, #C4942A, #E8BC5A);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.about-stat:nth-child(2) .about-stat-number {
  background: linear-gradient(135deg, #3A5430, #6B8F5C);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.about-stat:nth-child(3) .about-stat-number {
  background: linear-gradient(135deg, #B86B4A, #C49A7A);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.about-stat-label {
  font-family: 'Lato', sans-serif;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: #8B7B65;
}

// ── CTA Buttons ──
.about-ctas {
  display: flex;
  gap: 16px;
  margin-top: 32px;
  flex-wrap: wrap;
}

.about-btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 16px 32px;
  background: linear-gradient(135deg, #C4942A, #E8BC5A);
  color: #fff;
  font-family: 'Cinzel', serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-decoration: none;
  border-radius: 100px;
  box-shadow: 0 6px 24px rgba(196, 148, 42, 0.3);
  transition: all 0.4s ease;
}

.about-btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 32px rgba(196, 148, 42, 0.45);
}

