@media (max-width: 767px) {
  .transformation-quote {
    padding: 28px 24px;
  }

  .transformation-quote-text {
    font-size: 18px;
  }

  .timeline-year {
    font-size: 28px;
  }

  .timeline-title {
    font-size: 16px;
  }

  .timeline-desc {
    font-size: 13px;
  }
}

// ── Section Container ──
.final-cta-section {
  position: relative;
  overflow: hidden;
  background: linear-gradient(160deg, #EDE4D3 0%, #E5DDD0 100%);
}

// ── Decorative Background Elements ──
@keyframes float-slow {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-20px) rotate(3deg); }
}

@keyframes pulse-subtle {
  0%, 100% { opacity: 0.08; transform: scale(1); }
  50% { opacity: 0.12; transform: scale(1.05); }
}

.final-cta-bg-orb {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
  filter: blur(100px);
}

.final-cta-bg-orb-1 {
  top: -100px;
  right: -100px;
  width: 400px;
  height: 400px;
  background: #F5DFA0;
  animation: pulse-subtle 8s ease-in-out infinite;
}

.final-cta-bg-orb-2 {
  bottom: -100px;
  left: -100px;
  width: 350px;
  height: 350px;
  background: #6B8F5C;
  animation: pulse-subtle 10s ease-in-out infinite reverse;
}

.final-cta-bg-orb-3 {
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 600px;
  height: 600px;
  background: #F5DFA0;
  animation: pulse-subtle 12s ease-in-out infinite;
  opacity: 0.05;
}

// ── Decorative Lines ──
.final-cta-lines {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  pointer-events: none;
  overflow: hidden;
}

.final-cta-line {
  position: absolute;
  background: linear-gradient(to bottom, transparent, #F5DFA0, transparent);
  width: 1px;
  opacity: 0.3;
}

.final-cta-line-1 { left: 15%; height: 100%; animation: fadeIn 2s ease forwards; }
.final-cta-line-2 { left: 30%; height: 80%; animation: fadeIn 2s ease 0.3s forwards; }
.final-cta-line-3 { right: 30%; height: 80%; animation: fadeIn 2s ease 0.6s forwards; }
.final-cta-line-4 { right: 15%; height: 100%; animation: fadeIn 2s ease 0.9s forwards; }

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 0.3; }
}

// ── Main Content Wrapper ──
.final-cta-content {
  position: relative;
  z-index: 10;
  text-align: center;
  max-width: 720px;
  margin: 0 auto;
}

// ── Eyebrow ──
.final-cta-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
  opacity: 0;
  animation: fadeInUp 0.8s ease forwards 0.2s;
}

.final-cta-eyebrow-line {
  width: 48px;
  height: 1px;
  background: linear-gradient(to right, transparent, #C4942A);
}

.final-cta-eyebrow-line-r {
  width: 48px;
  height: 1px;
  background: linear-gradient(to left, transparent, #C4942A);
}

.final-cta-eyebrow-text {
  font-family: 'Cinzel', serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 6px;
  text-transform: uppercase;
  color: #C4942A;
}

// ── Main Title ──
.final-cta-title {
  font-family: 'Cinzel', serif;
  font-size: clamp(38px, 5vw, 64px);
  line-height: 1.1;
  letter-spacing: -1px;
  color: #2C2416;
  margin-bottom: 24px;
  opacity: 0;
  animation: fadeInUp 0.8s ease forwards 0.4s;
}

.final-cta-title-line {
  display: block;
}

.final-cta-title-accent {
  display: block;
  background: linear-gradient(135deg, #C4942A, #E8BC5A, #3A5430);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  background-size: 200% auto;
}

// ── Subtitle ──
.final-cta-subtitle {
  font-family: 'Lato', sans-serif;
  font-size: clamp(15px, 1.2vw, 18px);
  line-height: 1.85;
  color: #5C4A32;
  max-width: 560px;
  margin: 0 auto 40px;
  opacity: 0;
  animation: fadeInUp 0.8s ease forwards 0.6s;
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}

// ── CTA Buttons ──
.final-cta-buttons {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  flex-wrap: wrap;
  margin-bottom: 48px;
  opacity: 0;
  animation: fadeInUp 0.8s ease forwards 0.8s;
}

.final-cta-btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 20px 48px;
  background: linear-gradient(135deg, #C4942A, #E8BC5A);
  color: #fff;
  font-family: 'Cinzel', serif;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 3px;
  text-transform: uppercase;
  text-decoration: none;
  border-radius: 100px;
  box-shadow: 0 12px 40px rgba(196, 148, 42, 0.4), 0 0 80px rgba(196, 148, 42, 0.15);
  transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.final-cta-btn-primary:hover {
  transform: translateY(-4px) scale(1.02);
  box-shadow: 0 16px 52px rgba(196, 148, 42, 0.55), 0 0 100px rgba(196, 148, 42, 0.2);
}

.final-cta-btn-primary svg {
  width: 16px;
  height: 16px;
  fill: currentColor;
  transition: transform 0.3s ease;
}

.final-cta-btn-primary:hover svg {
  transform: translateX(4px);
}

.final-cta-btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 20px 40px;
  background: #FFFDF8;
  color: #2C2416;
  font-family: 'Cinzel', serif;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 3px;
  text-transform: uppercase;
  text-decoration: none;
  border-radius: 100px;
  border: 1.5px solid rgba(196, 148, 42, 0.35);
  box-shadow: 0 8px 24px rgba(44, 36, 22, 0.06);
  transition: all 0.4s ease;
}

.final-cta-btn-secondary:hover {
  background: #FFFDF8;
  border-color: #C4942A;
  transform: translateY(-3px);
  box-shadow: 0 12px 36px rgba(44, 36, 22, 0.1);
}

// ── Trust Indicators ──
.final-cta-trust {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 40px;
  flex-wrap: wrap;
  margin-bottom: 40px;
  opacity: 0;
  animation: fadeInUp 0.8s ease forwards 1s;
}

.final-cta-trust-item {
  display: flex;
  align-items: center;
  gap: 10px;
}

.final-cta-trust-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.final-cta-trust-text {
  font-family: 'Lato', sans-serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #8B7B65;
}

// ── Social Links ──
.final-cta-social {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  opacity: 0;
  animation: fadeInUp 0.8s ease forwards 1.2s;
}

.final-cta-social-label {
  font-family: 'Cinzel', serif;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #8B7B65;
  margin-right: 8px;
}

.final-cta-social-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: #FFFDF8;
  border: 1px solid rgba(196, 148, 42, 0.15);
  color: #5C4A32;
  text-decoration: none;
  transition: all 0.4s ease;
}

.final-cta-social-link:hover {
  background: #C4942A;
  border-color: #C4942A;
  color: #fff;
  transform: translateY(-3px);
  box-shadow: 0 8px 24px rgba(196, 148, 42, 0.3);
}

.final-cta-social-link svg {
  width: 18px;
  height: 18px;
  fill: currentColor;
}

// ── Decorative Divider ──
.final-cta-divider {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  margin-bottom: 32px;
  opacity: 0;
  animation: fadeInUp 0.8s ease forwards 1.1s;
}

.final-cta-divider-line {
  width: 80px;
  height: 1px;
  background: linear-gradient(to right, transparent, #B5A892);
}

.final-cta-divider-icon {
  font-size: 20px;
  color: #C4942A;
}

// ── Responsive ──
@media (max-width: 767px) {
  .final-cta-buttons {
    flex-direction: column;
  }

  .final-cta-btn-primary,
  .final-cta-btn-secondary {
    width: 100%;
    justify-content: center;
  }

  .final-cta-trust {
    flex-direction: column;
    gap: 16px;
  }

  .final-cta-social {
    flex-wrap: wrap;
  }
}

// ── Footer Container ──
.footer-section {
  position: relative;
  background: #2C2416;
  color: #8B7B65;
}

// ── Decorative Top Border ──
.footer-divider {
  width: 100%;
  height: 1px;
  background: linear-gradient(to right, transparent, #C4942A, transparent);
  position: relative;
}

.footer-divider::before {
  content: '✦';
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  background: #2C2416;
  padding: 0 20px;
  color: #C4942A;
  font-size: 12px;
}

// ── Footer Main Content ──
.footer-main {
  padding: 80px 0 60px;
}

// ── Footer Grid ──
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1.2fr;
  gap: 48px;
}

// ── Brand Column ──
.footer-brand {
  padding-right: 32px;
}

.footer-logo {
  font-family: 'Cinzel', serif;
  font-size: 28px;
  font-weight: 600;
  color: #FFFDF8;
  margin-bottom: 16px;
  letter-spacing: 1px;
}

.footer-tagline {
  font-family: 'Lato', sans-serif;
  font-size: 14px;
  line-height: 1.9;
  color: #8B7B65;
  margin-bottom: 24px;
  max-width: 280px;
}

.footer-social {
  display: flex;
  gap: 12px;
}

.footer-social-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255, 253, 248, 0.08);
  border: 1px solid rgba(255, 253, 248, 0.1);
  color: #8B7B65;
  text-decoration: none;
  transition: all 0.4s ease;
}

.footer-social-link:hover {
  background: #C4942A;
  border-color: #C4942A;
  color: #2C2416;
  transform: translateY(-3px);
}

.footer-social-link svg {
  width: 16px;
  height: 16px;
  fill: currentColor;
}

// ── Navigation Columns ──
.footer-nav-title {
  font-family: 'Cinzel', serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: #FFFDF8;
  margin-bottom: 20px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(255, 253, 248, 0.1);
}

.footer-nav-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.footer-nav-item {
  margin-bottom: 12px;
}

.footer-nav-link {
  font-family: 'Lato', sans-serif;
  font-size: 14px;
  color: #8B7B65;
  text-decoration: none;
  transition: all 0.3s ease;
  position: relative;
}

.footer-nav-link::before {
  content: '→';
  position: absolute;
  left: -16px;
  opacity: 0;
  color: #C4942A;
  transition: all 0.3s ease;
  transform: translateX(-4px);
}

.footer-nav-link:hover {
  color: #C4942A;
  padding-left: 8px;
}

.footer-nav-link:hover::before {
  opacity: 1;
  transform: translateX(0);
}

// ── Contact Column ──
.footer-contact-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 16px;
}

.footer-contact-icon {
  width: 20px;
  height: 20px;
  color: #C4942A;
  flex-shrink: 0;
  margin-top: 2px;
}

.footer-contact-icon svg {
  width: 100%;
  height: 100%;
  fill: currentColor;
}

.footer-contact-text {
  font-family: 'Lato', sans-serif;
  font-size: 14px;
  color: #8B7B65;
  line-height: 1.6;
}

.footer-contact-text a {
  color: #8B7B65;
  text-decoration: none;
  transition: color 0.3s ease;
}

.footer-contact-text a:hover {
  color: #C4942A;
}

// ── Newsletter Column ──
.footer-newsletter-text {
  font-family: 'Lato', sans-serif;
  font-size: 14px;
  line-height: 1.8;
  color: #8B7B65;
  margin-bottom: 20px;
}

.footer-newsletter-form {
  display: flex;
  gap: 8px;
}

.footer-newsletter-input {
  flex: 1;
  padding: 14px 16px;
  background: rgba(255, 253, 248, 0.06);
  border: 1px solid rgba(255, 253, 248, 0.12);
  border-radius: 8px;
  color: #FFFDF8;
  font-family: 'Lato', sans-serif;
  font-size: 13px;
  outline: none;
  transition: all 0.3s ease;
}

.footer-newsletter-input::placeholder {
  color: #8B7B65;
}

.footer-newsletter-input:focus {
  border-color: #C4942A;
  background: rgba(255, 253, 248, 0.08);
}

.footer-newsletter-btn {
  padding: 14px 20px;
  background: linear-gradient(135deg, #C4942A, #E8BC5A);
  border: none;
  border-radius: 8px;
  color: #2C2416;
  font-family: 'Cinzel', serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 1px;
  cursor: pointer;
  transition: all 0.4s ease;
  white-space: nowrap;
}

.footer-newsletter-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(196, 148, 42, 0.35);
}

// ── Footer Bottom ──
.footer-bottom {
  padding: 28px 0;
  border-top: 1px solid rgba(255, 253, 248, 0.08);
}

.footer-bottom-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-copyright {
  font-family: 'Lato', sans-serif;
  font-size: 12px;
  color: #8B7B65;
}

.footer-copyright a {
  color: #C4942A;
  text-decoration: none;
}

.footer-legal {
  display: flex;
  gap: 24px;
}

.footer-legal-link {
  font-family: 'Lato', sans-serif;
  font-size: 12px;
  color: #8B7B65;
  text-decoration: none;
  transition: color 0.3s ease;
}

.footer-legal-link:hover {
  color: #FFFDF8;
}

// ── Mystical Bottom Element ──
.footer-mystical {
  text-align: center;
  padding: 24px 0 0;
}

.footer-mystical-text {
  font-family: 'Cinzel', serif;
  font-size: 11px;
  letter-spacing: 4px;
  text-transform: uppercase;
  color: #8B7B65;
  opacity: 0.6;
}

.footer-mystical-symbol {
  font-size: 16px;
  color: #C4942A;
  margin-bottom: 8px;
  opacity: 0.4;
}

// ── Responsive ──
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 40px;
  }

  .footer-brand {
    grid-column: span 2;
    padding-right: 0;
  }
}

@media (max-width: 767px) {
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 36px;
  }

  .footer-brand {
    grid-column: span 1;
    text-align: center;
  }

  .footer-tagline {
    max-width: 100%;
  }

  .footer-social {
    justify-content: center;
  }

  .footer-nav-title {
    text-align: center;
  }

  .footer-nav-list {
    text-align: center;
  }

  .footer-contact-item {
    justify-content: center;
    text-align: left;
  }

  .footer-newsletter-form {
    flex-direction: column;
  }

  .footer-bottom-content {
    flex-direction: column;
    text-align: center;
  }

  .footer-legal {
    justify-content: center;
  }
}
